<script setup lang="ts">
import { computed, ref } from 'vue';
import { Head, Link } from '@inertiajs/vue3';

type Product={id:number;slug:string;name:string;category:string;brand:string;price:number;oldPrice?:number|null;image?:string|null;gallery:string[];badge?:string|null;rating:number;sold:number;stock:number;shortDescription?:string|null;description?:string|null;specs:Record<string,string>};
const props=defineProps<{product:Product|null}>();
const product=computed(()=>props.product);const selectedImage=ref(0);const quantity=ref(1);const added=ref(false);
function addToCart(){if(!product.value||product.value.stock<1)return;quantity.value=Math.min(quantity.value,product.value.stock);const cart=JSON.parse(localStorage.getItem('techstore_cart')??'[]');const existing=cart.find((item:any)=>item.id===product.value?.id);if(existing)existing.quantity=Math.min(product.value.stock,existing.quantity+quantity.value);else cart.push({id:product.value.id,name:product.value.name,price:product.value.price,image:product.value.image,quantity:quantity.value});localStorage.setItem('techstore_cart',JSON.stringify(cart));window.dispatchEvent(new Event('techstore-cart-updated'));added.value=true;window.setTimeout(()=>added.value=false,1800)}
function handleImageError(e:Event){(e.target as HTMLImageElement).style.display='none'}
</script>
<template><Head :title="product?.name||'Sản phẩm'"/><main v-if="product" class="product-detail-page"><div class="container product-detail-container"><nav class="detail-breadcrumb"><Link href="/">Trang chủ</Link><i class="bi bi-chevron-right"/><Link href="/products">Sản phẩm</Link><i class="bi bi-chevron-right"/><span>{{product.name}}</span></nav><section class="detail-card"><div class="row g-0"><div class="col-lg-6 detail-gallery-column"><div class="detail-main-image"><span v-if="product.badge" class="detail-image-badge">{{product.badge}}</span><img :src="product.gallery[selectedImage]||product.image||''" :alt="product.name" @error="handleImageError"/><div class="detail-image-fallback"><i class="bi bi-laptop"/><span>{{product.brand}}</span></div></div><div v-if="product.gallery.length>1" class="detail-thumbs"><button v-for="(image,index) in product.gallery" :key="`${image}-${index}`" type="button" :class="['detail-thumb',{active:selectedImage===index}]" @click="selectedImage=index"><img :src="image" :alt="`${product.name} ${index+1}`" @error="handleImageError"/></button></div></div><div class="col-lg-6 detail-info-column"><div class="detail-info"><div class="detail-category-line"><span class="detail-brand">{{product.brand}}</span><span class="detail-dot">•</span><span>{{product.category}}</span></div><h1 class="detail-title">{{product.name}}</h1><div class="detail-rating-row"><span class="rating-item"><i class="bi bi-star-fill"/> {{product.rating.toFixed(1)}}</span><span>{{product.sold}} đã bán</span><span>Mã SP: TS-{{String(product.id).padStart(4,'0')}}</span></div><p class="detail-description">{{product.shortDescription}}</p><div class="detail-price-box"><strong>{{new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(product.price)}}</strong><del v-if="product.oldPrice">{{new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(product.oldPrice)}}</del><span v-if="product.oldPrice" class="discount-pill">-{{Math.round((1-product.price/product.oldPrice)*100)}}%</span></div><div class="detail-stock"><span :class="{out:product.stock<1}"><i class="bi bi-check-circle-fill"/> {{product.stock<1?'Hết hàng':'Còn hàng'}}</span><b>{{product.stock}} sản phẩm</b></div><div class="detail-divider"/><div class="purchase-row"><div class="quantity-control"><button type="button" @click="quantity=Math.max(1,quantity-1)">−</button><span>{{quantity}}</span><button type="button" :disabled="quantity>=product.stock" @click="quantity=Math.min(product.stock,quantity+1)">+</button></div><button type="button" class="add-cart-btn" :class="{added}" :disabled="product.stock<1" @click="addToCart"><i :class="['bi',added?'bi-check-lg':'bi-cart-plus']"/> {{added?'Đã thêm vào giỏ':'Thêm vào giỏ hàng'}}</button></div><div class="detail-benefits"><div class="benefit-item"><span class="benefit-icon"><i class="bi bi-shield-check"/></span><span><b>Chính hãng</b><small>Bảo hành theo nhà sản xuất</small></span></div><div class="benefit-item"><span class="benefit-icon"><i class="bi bi-truck"/></span><span><b>Giao hàng toàn quốc</b><small>Đóng gói an toàn, theo dõi đơn</small></span></div><div class="benefit-item"><span class="benefit-icon"><i class="bi bi-arrow-repeat"/></span><span><b>Đổi trả thuận tiện</b><small>Hỗ trợ theo chính sách TechStore</small></span></div></div></div></div></div></section><section class="row g-4 detail-lower-row"><div class="col-lg-8"><article class="detail-panel"><div class="panel-heading"><div><span class="panel-kicker">THÔNG TIN</span><h2>Thông tin sản phẩm</h2></div><span class="panel-heading-icon"><i class="bi bi-info-circle"/></span></div><p class="product-description">{{product.description}}</p><div class="spec-grid"><div v-for="(value,key) in product.specs" :key="key" class="spec-item"><span>{{key}}</span><strong>{{value}}</strong></div></div></article></div><div class="col-lg-4"><article class="detail-panel commitment-panel"><div class="panel-heading"><div><span class="panel-kicker">TECHSTORE</span><h2>Cam kết</h2></div><span class="panel-heading-icon"><i class="bi bi-patch-check"/></span></div><ul class="commit-list"><li><i class="bi bi-patch-check-fill"/>Sản phẩm chính hãng</li><li><i class="bi bi-box-seam"/>Đóng gói chống sốc</li><li><i class="bi bi-arrow-repeat"/>Hỗ trợ đổi trả</li><li><i class="bi bi-headset"/>Tư vấn kỹ thuật</li></ul></article></div></section></div></main><div v-else class="container py-5"><div class="empty-catalog"><i class="bi bi-box-seam"/><h3>Không tìm thấy sản phẩm</h3><Link href="/products" class="btn btn-primary mt-2">Quay lại sản phẩm</Link></div></div></template>
